    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    edges = [
        [grid[r][0] for r in range(h)],
        [grid[r][-1] for r in range(h)],
        grid[0][:],
        grid[-1][:]
    ]

    def segments(values, color):
        result = []
        i = 0
        while i < len(values):
            if values[i] != color:
                i += 1
                continue
            j = i
            while j + 1 < len(values) and values[j + 1] == color:
                j += 1
            result.append((i, j))
            i = j + 1
        return result

    # Find the non-background color occurring in contiguous segments on
    # a pair of opposite edges.
    choices = []
    for color in set(x for row in grid for x in row):
        if color == background:
            continue
        for a, b, axis in ((0, 1, "v"), (2, 3, "h")):
            sa, sb = segments(edges[a], color), segments(edges[b], color)
            if sa and sb:
                choices.append((sum(y - x + 1 for x, y in sa + sb),
                                color, axis, sa, sb))
    if not choices:
        return [row[:] for row in grid]

    _, portal, axis, side_a, side_b = max(choices)
    sides = [side_a, side_b]
    out = [row[:] for row in grid]

    markers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] != background and grid[r][c] != portal]

    for r, c, color in markers:
        coordinate = r if axis == "v" else c

        # Locate the portal segment whose coordinate matches this marker.
        source_side = source_run = None
        for side in (0, 1):
            for run in sides[side]:
                if run[0] <= coordinate <= run[1]:
                    source_side, source_run = side, run
                    break
            if source_side is not None:
                break
        if source_side is None:
            continue

        target_run = sides[1 - source_side][0]
        offset = coordinate - source_run[0]
        target_coordinate = min(target_run[0] + offset, target_run[1])

        if axis == "v":
            # Extend the marker toward its matching left/right portal.
            edge_col = 0 if source_side == 0 else w - 1
            step = -1 if edge_col == 0 else 1
            cc = c + step
            while 0 <= cc < w and cc != edge_col:
                if out[r][cc] == background:
                    out[r][cc] = color
                cc += step
            out[r][c] = 4

            # Project its offset across the grid from the opposite portal.
            for cc in range(w):
                if out[target_coordinate][cc] == background:
                    out[target_coordinate][cc] = color
        else:
            # Extend toward the matching top/bottom portal, excluding edge.
            edge_row = 0 if source_side == 0 else h - 1
            step = -1 if edge_row == 0 else 1
            rr = r + step
            while 0 <= rr < h and rr != edge_row:
